// Label-array oracle: label[i] is the smallest element of i's set.
struct Oracle {
  std::vector<u32> label;
  explicit Oracle(u32 n) : label(n) {
    for (u32 i = 0; i < n; ++i) label[i] = i;
  }
  bool unite(u32 a, u32 b) {
    const u32 la = label[a], lb = label[b];
    if (la == lb) return false;
    const u32 lo = la < lb ? la : lb, hi = la < lb ? lb : la;
    for (u32& l : label) {
      if (l == hi) l = lo;
    }
    return true;
  }
  u32 count() const {
    u32 c = 0;
    for (u32 i = 0; i < label.size(); ++i) {
      if (label[i] == i) ++c;
    }
    return c;
  }
};

struct Rng {
  u32 s;
  u32 next() {
    s = s * 1664525u + 1013904223u;
    return s >> 8;
  }
};

